#include <stdio.h>
#include <string.h>

int main(void) {
    char line[32];
    if (fgets(line, sizeof line, stdin) == NULL) {
        puts("No input line was read");
        return 1;
    }
    printf("Received %zu bytes\n", strlen(line));
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char line[8];
    if (fgets(line, sizeof line, stdin) == NULL) return 1;
    if (strchr(line, '\\n') == NULL && !feof(stdin))
        puts("The line may be longer than the buffer");
    return 0;
}
